function validate([n, k]) {
  if (!Number.isInteger(n) || n < 2 || n > 50) return 'n is an integer from 2 to 50.';
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is an integer from 1 to 50.';
  return null;
}

